#!/usr/bin/env python3
"""Write the verification narrative from actual captured reports, not forecasts."""
from pathlib import Path
import json,subprocess
A=Path(__file__).resolve().parents[2];E=A/'references/evidence'
def load(name):
 p=E/name
 return json.loads(p.read_text())if p.exists()else None
initial=load('initial-remote-state.json');media=load('current-media-verification.json');validation=load('archive-validation.json');push=load('primary-push-verification.json');stage=load('staged-review.json')
lines=['# Verification report\n','## Evidence standard\n','Tests below are labeled **historical**, **fresh**, or **not run**. A source-code inspection or an existing JSON report is not mislabeled as a new render. No new video generation, Flick installation, or unrelated repository mutation is part of this archive task. Credentials are excluded.\n','## 1. Existing repository inspection — fresh\n',f"Repository `{initial['repository']}` was public on `{initial['default_branch']}`, pre-archive tip `{initial['head']}`. Fourteen tracked files matched the workspace; six prior commits were recovered; no root `.gitignore`, `.gitattributes`, pre-existing archive, or native skill convention existed. Local `.git` was initially absent.\n",'The public tree/history and no-Git baseline are retained in [initial-remote-state.json](references/evidence/initial-remote-state.json). Metadata/index attachment to that same remote used no worktree checkout. `git diff --name-status` was empty immediately afterward; pre-existing untracked files remained.\n','## 2. Existing delivered media — fresh read-only checks\n']
if media:
 lines+=['Command actually run: `python ai-work-session/references/scripts/verify_media.py`.\n',f"Captured at `{media['capturedAtUtc']}`; result **{media['result']}**. Method: full OpenCV video decode, SHA-256 and comparison with the initial remote Git blob IDs. No MP4 was encoded.\n",'| Version | Dimensions | FPS | Decoded frames | Bytes | SHA-256 |\n','|---|---|---:|---:|---:|---|\n']
 for r in media['videos']:lines.append(f"| {r['version']} | {r['width']} × {r['height']} | {r['fps']} | {r['decodedFrames']} | {r['bytes']:,} | `{r['sha256']}` |\n")
 lines+=['\n[Full current media report](references/evidence/current-media-verification.json). This does not independently reanalyse audio. Matching complete-file bytes link the existing files to the historical audio checks below.\n']
else:lines+=['Fresh media rechecks are not yet recorded at this report revision. Do not infer they passed.\n']
lines+=['## 3. Historical export tests — not rerun as audio analysis now\n','| Version | Whole FFmpeg decode | Measured voice lag | Integrated loudness | True peak |\n','|---|---|---:|---:|---:|\n','| V1 | passed, empty decode stderr | 0 ms | −15.89 LUFS | −1.70 dBTP |\n','| V2 | passed | 0 ms | −15.90 LUFS | −1.64 dBTP |\n','| V3 | passed | 0 ms | −15.90 LUFS | −1.65 dBTP |\n','\nReports: [V1](references/evidence/analysis/export-qc.json), [V2](references/evidence/analysis/editorial-v2-export-qc.json), [V3](references/evidence/analysis/morph-v3-export-qc.json). Voice timing used a specific one-to-four-second cross-correlation check, not a recorded human proofreading of every word. Use FFmpeg `input_*` loudness fields for actual delivered-file measurements; `output_*` were null-analysis target results, not a second encode.\n','Historical public MP4 checks returned HTTP 206 and MP4 signature true; V2/V3 upload transactions checked prior video hashes unchanged. Actual commits are in the delivery JSON and recovered Git history.\n','## 4. Archive/skill/source validation — fresh\n']
if validation:
 c=validation['checks'];lines +=[f"Recorded command: `python ai-work-session/references/scripts/validate_archive.py --check-original-workspace`. Captured at `{validation['capturedAtUtc']}`; result **{validation['result']}**.\n",f"- Required files: {c['requiredFiles']['expected']}; missing: {len(c['requiredFiles']['missing'])}.\n",f"- Skill: Agent Skills YAML/Markdown, name `{c['skill'].get('name')}`, {c['skill'].get('lines')} lines; directory/name match and frontmatter constraints checked.\n",f"- Relative Markdown links checked: {c['localLinks']['checked']}; broken: {len(c['localLinks']['broken'])}. External URLs are not all refetched merely to validate syntax.\n",f"- Python AST syntax parsed: {c['pythonAst']['checked']} files; source not imported or executed for this test.\n",f"- JSON parsed: {c['json']['parsed']} files.\n",f"- Exact copied artifacts: {c['exactCopies']['checked']}; mismatches: {len(c['exactCopies']['mismatches'])}.\n"]
 o=c['originalWorkspace']
 if o.get('strict'):lines.append(f"- Original workspace files checked: {o['checked']}; changed: {len(o['changed'])}; missing: {len(o['missing'])}.\n")
 sec=c['secretScan'];lines.append(f"- Secret scan: {sec['filesScanned']} files; {sec['knownValuesChecked']} supplied sensitive values checked in memory (including direct/base64/URL encodings); detected findings: {len(sec['findings'])}. No values were printed or stored.\n")
 lines.append('\n[Machine report](references/evidence/archive-validation.json). The report is a timestamped check, not a claim that no unknown secret could ever exist. Staged scope is separately checked before commit. Native activation in a specific AI client is **not tested**; only portable format and documented explicit loading are verified.\n')
else:lines.append('The archive validator has not yet produced a report at this revision. No PASS is asserted.\n')
lines+=['## 5. Git stage/diff review\n']
if stage:
 lines+=[f"Captured at `{stage['capturedAtUtc']}`: {stage['pathCount']} staged paths; all inside `ai-work-session/`: **{stage['onlyArchive']}**; `git diff --cached --check` exit code: **{stage['whitespaceExitCode']}**.\n",'The complete staged textual diff was inspected, copied binary inputs were hash/provenance checked, and source syntax/known-secret scans ran before commit. See [staged review](references/evidence/staged-review.json) for commands/results and prior tracked-file preservation. The staged-review evidence file itself is added afterward, so its own future presence/hash is not pretended to have been in its earlier inventory. A final no-write scope validation is performed after the evidence is staged.\n']
else:lines.append('Staged diff/scope review is not yet recorded at this report revision. Only the dedicated folder is authorized for staging.\n')
lines+=['## 6. Commit / push verification\n']
if push:
 lines +=[f"Primary archive commit: `{push['archiveCommit']}` on `{push['branch']}`.\n",f"Normal push completed; remote tip at the recorded check was `{push['remoteTipAtCheck']}`; matches primary commit: **{push['tipMatched']}**. Existing original tracked blobs preserved: **{push['originalTrackedFilesPreserved']}**.\n",f"Public folder and commit were checked at `{push['capturedAtUtc']}`; verified archive files: {push['verifiedArchiveFiles']}.\n",f"[Public archive folder]({push['folderUrl']}) · [Primary archive commit]({push['commitUrl']}) · [Machine evidence](references/evidence/primary-push-verification.json).\n",'This narrative is an evidence follow-up committed after the primary push was observed. It cannot embed its own introducing commit hash without self-reference. The final delivery tip is obtained from Git history / the final response and verified remotely after the follow-up push. Primary verification is a real earlier checkpoint, not a claim the primary hash remains the latest tip forever.\n']
else:lines.append('No primary push-verification record exists at this revision. Commit/push are not claimed complete until a real remote check is captured.\n')
lines+=['## 7. Not tested / limitations\n','- No new render, replacement narrator, face generation, third-party posting, stock Flick installation or Remotion/Flick batch benchmark was run in this task.\n','- The actual Instagram reel was not supplied; the earlier Flick audit evaluated the user-reported claim and public source only.\n','- No historical dependency lock, raw platform transcript export, complete shell history, original process-log files or missing caches were recovered.\n','- Human transcript proofreading and actual native skill discovery/registration are not claimed.\n','- All shared credentials are treated as exposed; rotation status remains unknown. Public-reference binaries are not unnecessarily republished.\n','- Existing root README/video/source bytes are not changed; any newly created operational Git metadata is distinct from the tracked archive deliverables.\n']
(A/'VERIFICATION_REPORT.md').write_text(''.join(lines));print('VERIFICATION_REPORT.md updated from actual available evidence.')
